import{_ as e,o as t,c as n,a2 as s}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Assets and liabilities","description":"","frontmatter":{"title":"Assets and liabilities"},"headers":[],"relativePath":"docs/personal-finance/assets-and-liabilities.md","filePath":"docs/personal-finance/assets-and-liabilities.md","lastUpdated":1790443712000}'),i={name:"docs/personal-finance/assets-and-liabilities.md"};function o(r,a,l,d,c,h){return t(),n("div",null,[...a[0]||(a[0]=[s('<h1 id="assets-and-liabilities" tabindex="-1">Assets and liabilities <a class="header-anchor" href="#assets-and-liabilities" aria-label="Permalink to &quot;Assets and liabilities&quot;">​</a></h1><p>A Fixed Assets project tracks things no bank statement ever reports: real estate, vehicles, private company stock, and the loans against them — all entered by hand.</p><h2 id="adding-an-asset" tabindex="-1">Adding an asset <a class="header-anchor" href="#adding-an-asset" aria-label="Permalink to &quot;Adding an asset&quot;">​</a></h2><p>Use <strong>Add Asset</strong> to record a name, type, and value. For real estate, adding an address unlocks a one-click <strong>Zillow</strong> lookup that suggests a current value estimate for you to review and accept.</p><p>Every asset keeps a history of its value over time, which you can expand and edit, so changes are tracked rather than overwriting a single number.</p><h2 id="adding-a-liability" tabindex="-1">Adding a liability <a class="header-anchor" href="#adding-a-liability" aria-label="Permalink to &quot;Adding a liability&quot;">​</a></h2><p>Use <strong>Add Liability</strong> to record a loan against an asset: the lender, loan amount, loan date, interest rate, and payment amount and frequency. If you don&#39;t know the payment amount, a <strong>Calculate payment</strong> button derives it from the loan amount, rate, and term.</p><h2 id="linking-loan-payments" tabindex="-1">Linking loan payments <a class="header-anchor" href="#linking-loan-payments" aria-label="Permalink to &quot;Linking loan payments&quot;">​</a></h2><p>When a loan payment shows up in a linked Income/Spending or Combined Finance project, use <strong>Change link</strong> to connect that transaction to the liability it belongs to. Once linked, OrbySystems automatically figures out how much of each payment went to principal versus interest, so the payment is tracked as debt paydown rather than double-counted as ordinary spending.</p><p>For the rare payment that bundles the loan payment with something else (like escrow), use <strong>Split payment</strong> to manually specify the principal portion.</p><h2 id="what-you-can-see" tabindex="-1">What you can see <a class="header-anchor" href="#what-you-can-see" aria-label="Permalink to &quot;What you can see&quot;">​</a></h2><p>Dashboards summarize what you own and what you owe: assets by type, equity by asset, and a debt overview across every tracked loan.</p>',12)])])}const m=e(i,[["render",o]]);export{u as __pageData,m as default};
